package domain

import "time"

// PersonalAgentTool is a capability supplied by the host application's gateway.
// Roles are generated by the planner; tool implementations remain with the host.
type PersonalAgentTool struct {
	Name        string         `json:"name"`
	Description string         `json:"description"`
	InputSchema map[string]any `json:"inputSchema"`
	Effect      string         `json:"effect"` // read or write
	// RequiredPhase is a host-owned completion condition, never set by a planner.
	RequiredPhase string `json:"requiredPhase,omitempty"` // empty, analysis, execution
}

type PersonalAgentSpec struct {
	ID             string   `json:"id"`
	Name           string   `json:"name"`
	Purpose        string   `json:"purpose"`
	Instructions   string   `json:"instructions"`
	Tools          []string `json:"tools"`
	DependsOn      []string `json:"dependsOn"`
	Phase          string   `json:"phase"` // analysis or execution
	OutputContract string   `json:"outputContract"`
}

type PersonalAgentPlan struct {
	Name        string              `json:"name"`
	Description string              `json:"description"`
	MatchHints  []string            `json:"matchHints"`
	Agents      []PersonalAgentSpec `json:"agents"`
}

type PersonalAgentToolCall struct {
	ID        string         `json:"id"`
	Name      string         `json:"name"`
	Arguments map[string]any `json:"arguments"`
	Result    any            `json:"result,omitempty"`
	Effect    string         `json:"effect"`
	Status    string         `json:"status"` // running, succeeded, failed, unknown
	Error     string         `json:"error,omitempty"`
}

type PersonalAgentRun struct {
	AgentID    string                  `json:"agentId"`
	Status     string                  `json:"status"`
	Output     any                     `json:"output,omitempty"`
	ToolCalls  []PersonalAgentToolCall `json:"toolCalls"`
	Error      string                  `json:"error,omitempty"`
	StartedAt  *time.Time              `json:"startedAt,omitempty"`
	FinishedAt *time.Time              `json:"finishedAt,omitempty"`
}

type PersonalAgentEvent struct {
	ID      string    `json:"id"`
	Type    string    `json:"type"`
	Message string    `json:"message"`
	AgentID string    `json:"agentId,omitempty"`
	At      time.Time `json:"at"`
}

type PersonalAgentTask struct {
	ID               string               `json:"id"`
	ProjectID        string               `json:"projectId"`
	ActorID          string               `json:"actorId"`
	Request          string               `json:"request"`
	Context          map[string]any       `json:"context"`
	SourceSOPID      string               `json:"sourceSopId,omitempty"`
	Status           string               `json:"status"`
	Revision         int                  `json:"revision"`
	PlanHash         string               `json:"planHash,omitempty"`
	Plan             PersonalAgentPlan    `json:"plan"`
	Runs             []PersonalAgentRun   `json:"runs"`
	Feedback         []string             `json:"feedback"`
	Events           []PersonalAgentEvent `json:"events"`
	SOPID            string               `json:"sopId,omitempty"`
	Error            string               `json:"error,omitempty"`
	ApprovedAt       *time.Time           `json:"approvedAt,omitempty"`
	ApprovedRevision int                  `json:"approvedRevision,omitempty"`
	CreatedAt        time.Time            `json:"createdAt"`
	UpdatedAt        time.Time            `json:"updatedAt"`
}

// PersonalAgentSOP is immutable: every publication gets a new ID and embeds
// all generated role definitions. Reusing it creates fresh task/run instances.
type PersonalAgentSOP struct {
	ID           string            `json:"id"`
	ProjectID    string            `json:"projectId"`
	ActorID      string            `json:"actorId"`
	Name         string            `json:"name"`
	Description  string            `json:"description"`
	MatchHints   []string          `json:"matchHints"`
	Plan         PersonalAgentPlan `json:"plan"`
	Version      int               `json:"version"`
	SourceTaskID string            `json:"sourceTaskId"`
	CreatedAt    time.Time         `json:"createdAt"`
}
